const int MaxLine = 512;

public static bool TryParseRow(ReadOnlySpan<char> line, out int userId, out int score)
{
    userId = score = 0;
    var firstComma = line.IndexOf(',');
    if (firstComma < 0) return false;
    if (!int.TryParse(line[..firstComma], out userId)) return false;
    return int.TryParse(line[(firstComma + 1)..], out score);
}

