public static IEnumerable<RowDto> ParseRows(StreamReader reader)
{
    string? line;
    while ((line = reader.ReadLine()) is not null)
    {
        if (TryParseRow(line.AsSpan(), out var uid, out var score))
            yield return new RowDto(uid, score);
    }
}

const int MaxLineBytes = 4096;

bool TryReadLine(Span<byte> stackBuf, StreamReader reader, out ReadOnlySpan<char> line)
{
    var raw = reader.ReadLine();
    if (raw is null) { line = default; return false; }
    if (raw.Length > MaxLineBytes)
        throw new InvalidDataException($"line exceeds {MaxLineBytes} bytes");
    line = raw.AsSpan();
    return true;
}
